import { EntityTfError } from "../../engine/entity.js";
import { expr, scopedResourceLabel, tsLabelToTfLabel } from "../../engine/tf/index.js";
import { APP_RESOURCE_TYPE } from "../app/module.js";
import { CONNECTOR_ORG_BAG } from "../org/connector.js";
import { AGENT_EVALUATION_RESOURCE_TYPE } from "./module.js";
export function agentEvaluationToTf(entity, opts) {
    if (entity.kind !== "agent-evaluation") {
        throw new EntityTfError(`agentEvaluationToTf expects kind "agent-evaluation"; got "${entity.kind}"`);
    }
    const evaluation = entity.payload;
    if (evaluation === null || evaluation.app?.refName !== opts.appRefName) {
        throw new EntityTfError(`agent evaluation "${entity.refName}" does not reference owning app "${opts.appRefName}"`);
    }
    const connectorKey = evaluation.connector?.parent !== undefined
        ? `${evaluation.connector.parent}.${evaluation.connector.refName ?? ""}`
        : evaluation.connector?.refName ?? "";
    const connector = opts.orgRefs.byTsLabel(CONNECTOR_ORG_BAG, connectorKey);
    if (connector === undefined) {
        throw new EntityTfError(`agent evaluation "${entity.refName}": connector token "${connectorKey}" is not in the org catalog — re-run \`elementum pull org --data-only\``);
    }
    const label = scopedResourceLabel(opts.appTfLabel, tsLabelToTfLabel(entity.refName), "app");
    const block = {
        kind: "resource",
        type: AGENT_EVALUATION_RESOURCE_TYPE,
        label,
        attrs: {
            app_id: expr.resourceAttr(APP_RESOURCE_TYPE, opts.appTfLabel, ["id"]),
            name: evaluation.name ?? "",
            prompt: evaluation.prompt ?? "",
            ai_provider_connector_id: expr.dataAttr("elementum_ai_provider_connector", connector.tfLabel, ["id"]),
            passing_threshold: evaluation.passingThreshold ?? 0,
        },
    };
    return { blocks: [block], address: `${AGENT_EVALUATION_RESOURCE_TYPE}.${label}` };
}
